('anatomie-deltoid',1,'{"id":"anatomie-deltoid","correct":0,"studyYears":[2],"fr":{"title":"Quelle action caractérise les fibres moyennes du muscle repéré par A ?","context":"Le repère A désigne la structure à étudier. La silhouette indique une position générale ; les proportions et les trajets sont simplifiés.","options":["Abduction du bras","Extension du genou","Flexion des doigts","Adduction des doigts"],"reasoning":"Les fibres moyennes du deltoïde écartent le bras du tronc.","diagram":{"structureId":"deltoid","view":"front"}},"en":{"title":"Which action characterises the middle fibres of the muscle marked A?","context":"Marker A identifies the structure to study. The silhouette shows a general location; proportions and pathways are simplified.","options":["Arm abduction","Knee extension","Finger flexion","Finger adduction"],"reasoning":"The middle fibres of the deltoid move the arm away from the trunk.","diagram":{"structureId":"deltoid","view":"front"}}}'::jsonb),
('anatomie-pectoralis-major',1,'{"id":"anatomie-pectoralis-major","correct":3,"studyYears":[2],"fr":{"title":"Quel muscle superficiel du thorax est repéré par A ?","context":"Le repère A désigne la structure à étudier. La silhouette indique une position générale ; les proportions et les trajets sont simplifiés.","options":["Grand dorsal","Droit de l’abdomen","Trapèze","Grand pectoral"],"reasoning":"Le grand pectoral occupe la partie antérieure supérieure du thorax.","diagram":{"structureId":"pectoralis-major","view":"front"}},"en":{"title":"Which superficial chest muscle is marked A?","context":"Marker A identifies the structure to study. The silhouette shows a general location; proportions and pathways are simplified.","options":["Latissimus dorsi","Rectus abdominis","Trapezius","Pectoralis major"],"reasoning":"Pectoralis major covers the upper anterior part of the thorax.","diagram":{"structureId":"pectoralis-major","view":"front"}}}'::jsonb),
('anatomie-rectus-abdominis',1,'{"id":"anatomie-rectus-abdominis","correct":2,"studyYears":[2],"fr":{"title":"Quelle action appartient au muscle de la paroi abdominale repéré par A ?","context":"Le repère A désigne la structure à étudier. La silhouette indique une position générale ; les proportions et les trajets sont simplifiés.","options":["Abduction du bras","Dorsiflexion du pied","Flexion du tronc","Extension du coude"],"reasoning":"Le droit de l’abdomen contribue à la flexion du tronc.","diagram":{"structureId":"rectus-abdominis","view":"front"}},"en":{"title":"Which action is performed by the abdominal wall muscle marked A?","context":"Marker A identifies the structure to study. The silhouette shows a general location; proportions and pathways are simplified.","options":["Arm abduction","Foot dorsiflexion","Trunk flexion","Elbow extension"],"reasoning":"Rectus abdominis contributes to trunk flexion.","diagram":{"structureId":"rectus-abdominis","view":"front"}}}'::jsonb),
('anatomie-quadriceps',1,'{"id":"anatomie-quadriceps","correct":1,"studyYears":[2],"fr":{"title":"Quel mouvement principal réalise le groupe musculaire repéré par A ?","context":"Le repère A désigne la structure à étudier. La silhouette indique une position générale ; les proportions et les trajets sont simplifiés.","options":["Extension du coude","Extension du genou","Flexion du genou","Flexion plantaire"],"reasoning":"Le quadriceps étend le genou par l’appareil extenseur.","diagram":{"structureId":"quadriceps","view":"front"}},"en":{"title":"What is the main movement produced by the muscle group marked A?","context":"Marker A identifies the structure to study. The silhouette shows a general location; proportions and pathways are simplified.","options":["Elbow extension","Knee extension","Knee flexion","Plantar flexion"],"reasoning":"The quadriceps extends the knee through the extensor mechanism.","diagram":{"structureId":"quadriceps","view":"front"}}}'::jsonb),
('anatomie-median-nerve',1,'{"id":"anatomie-median-nerve","correct":0,"studyYears":[3],"fr":{"title":"Le nerf repéré par A traverse le canal carpien. Lequel est-ce ?","context":"Le repère A désigne la structure à étudier. La silhouette indique une position générale ; les proportions et les trajets sont simplifiés.","options":["Nerf médian","Nerf ulnaire","Nerf radial","Nerf axillaire"],"reasoning":"Le nerf médian traverse le canal carpien.","diagram":{"structureId":"median-nerve","view":"front"}},"en":{"title":"The nerve marked A passes through the carpal tunnel. Which nerve is it?","context":"Marker A identifies the structure to study. The silhouette shows a general location; proportions and pathways are simplified.","options":["Median nerve","Ulnar nerve","Radial nerve","Axillary nerve"],"reasoning":"The median nerve passes through the carpal tunnel.","diagram":{"structureId":"median-nerve","view":"front"}}}'::jsonb),
('anatomie-ulnar-nerve',1,'{"id":"anatomie-ulnar-nerve","correct":3,"studyYears":[3],"fr":{"title":"Quel nerf repéré par A passe en arrière de l’épicondyle médial de l’humérus ?","context":"Le repère A désigne la structure à étudier. La silhouette indique une position générale ; les proportions et les trajets sont simplifiés.","options":["Nerf médian","Nerf axillaire","Nerf fémoral","Nerf ulnaire"],"reasoning":"Le nerf ulnaire contourne l’épicondyle médial en arrière.","diagram":{"structureId":"ulnar-nerve","view":"front"}},"en":{"title":"Which nerve marked A passes behind the medial epicondyle of the humerus?","context":"Marker A identifies the structure to study. The silhouette shows a general location; proportions and pathways are simplified.","options":["Median nerve","Axillary nerve","Femoral nerve","Ulnar nerve"],"reasoning":"The ulnar nerve passes posterior to the medial epicondyle.","diagram":{"structureId":"ulnar-nerve","view":"front"}}}'::jsonb),
('anatomie-radial-nerve',1,'{"id":"anatomie-radial-nerve","correct":2,"studyYears":[3],"fr":{"title":"Quelle fonction motrice est notamment associée au nerf repéré par A ?","context":"Le repère A désigne la structure à étudier. La silhouette indique une position générale ; les proportions et les trajets sont simplifiés.","options":["Adduction des doigts","Extension du genou","Extension du poignet","Opposition du pouce"],"reasoning":"Le nerf radial et ses branches innervent les extenseurs du poignet.","diagram":{"structureId":"radial-nerve","view":"back"}},"en":{"title":"Which motor function is associated with the nerve marked A?","context":"Marker A identifies the structure to study. The silhouette shows a general location; proportions and pathways are simplified.","options":["Finger adduction","Knee extension","Wrist extension","Thumb opposition"],"reasoning":"The radial nerve and its branches supply the wrist extensors.","diagram":{"structureId":"radial-nerve","view":"back"}}}'::jsonb),
